import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.DnrXFDHb.js";const b=JSON.parse('{"title":"Tokenization 与 Embedding","description":"","frontmatter":{},"headers":[],"relativePath":"llm/tokenization-embedding.md","filePath":"llm/tokenization-embedding.md","lastUpdated":1788308924000}'),o={name:"llm/tokenization-embedding.md"};function d(l,e,r,s,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="tokenization-与-embedding" tabindex="-1">Tokenization 与 Embedding <a class="header-anchor" href="#tokenization-与-embedding" aria-label="Permalink to &quot;Tokenization 与 Embedding&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> Tokenizer 先把文本映射为 Vocabulary 中的 Token ID，模型再把 ID 查表变成向量；通用语义 Embedding 和 AI 绘画中的 Textual Inversion 是相关但不同的概念。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/llm/basics">大模型入门</a>，知道 LLM 会根据上下文预测后续 Token。</li><li>知道 Embedding 的直觉是把对象表示成可计算的向量。</li><li>不要求使用任何在线模型或商业 API。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>解释 Tokenizer、Token、Vocabulary 和 Token ID 的关系。</li><li>描述文本从字符串变成模型输入向量的基本流程。</li><li>区分 Token Embedding、位置表示和通用语义 Embedding。</li><li>说明 Textual Inversion 为什么不能与通用 Embedding 混为一谈。</li><li>理解中英文 Token 数量没有固定换算比例，并判断它对上下文、延迟和成本的影响。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="tokenizer-和-vocabulary" tabindex="-1">Tokenizer 和 Vocabulary <a class="header-anchor" href="#tokenizer-和-vocabulary" aria-label="Permalink to &quot;Tokenizer 和 Vocabulary&quot;">​</a></h3><p><strong>Tokenizer</strong> 是把字符串编码成 Token 序列、也把 Token 序列解码回文本的组件。它通常包含规范化、预切分、子词算法和特殊 Token 处理等步骤。</p><p><strong>Vocabulary</strong> 是 Token 与整数 ID 的映射表。Vocabulary 里可能包含：</p><ul><li>完整词或常见汉字。</li><li>词根、前后缀和子词片段。</li><li>标点、空格模式或字节片段。</li><li><code>[BOS]</code>、<code>[EOS]</code>、<code>[PAD]</code> 等特殊 Token。</li></ul><p>不同模型可能使用 BPE、WordPiece、Unigram、SentencePiece 或字节级方案。即使输入文本完全相同，只要 Tokenizer 或 Vocabulary 不同，切分和 Token 数量就可能不同。</p><h3 id="文本如何变成-token-id" tabindex="-1">文本如何变成 Token ID <a class="header-anchor" href="#文本如何变成-token-id" aria-label="Permalink to &quot;文本如何变成 Token ID&quot;">​</a></h3><p>以常见子词 Tokenizer 为例，流程可以粗略理解为：</p><ol><li>规范化文本，例如处理 Unicode 或大小写；具体规则取决于模型。</li><li>做预切分，例如识别空格、标点或字节边界。</li><li>根据已训练好的子词规则组合或拆分片段。</li><li>在 Vocabulary 中查出每个 Token 的整数 ID。</li><li>按模型要求加入起止、分隔等特殊 Token。</li></ol><p>Token ID 只是索引，不包含可直接解释的语义距离。ID 为 <code>120</code> 的 Token 不会天然比 ID 为 <code>20</code> 的 Token “多 100 单位含义”。</p><h3 id="token-embedding-与位置表示" tabindex="-1">Token Embedding 与位置表示 <a class="header-anchor" href="#token-embedding-与位置表示" aria-label="Permalink to &quot;Token Embedding 与位置表示&quot;">​</a></h3><p>神经网络不能直接处理字符串。模型内部有一张 Token Embedding 矩阵，每个 Token ID 对应其中一行向量：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Token ID -&gt; 查 Embedding 矩阵 -&gt; 初始 Token 向量</span></span></code></pre></div><p>初始 Token Embedding 表示“这是哪个 Token”，但序列还需要位置信息。不同架构可能：</p><ul><li>把可学习或固定的位置向量与 Token Embedding 相加。</li><li>在 Attention 中使用旋转位置编码（RoPE，一种给 token 注入位置信息的方法）。</li><li>使用相对位置偏置或其他位置机制。</li></ul><p>经过多层 Transformer 后，每个位置得到的是结合上下文的隐藏状态。同一个 Token 在“苹果很好吃”和“苹果发布新品”中的初始 Token Embedding 可以相同，但后续上下文表示会不同。</p><h3 id="通用-embedding-与语义相似度" tabindex="-1">通用 Embedding 与语义相似度 <a class="header-anchor" href="#通用-embedding-与语义相似度" aria-label="Permalink to &quot;通用 Embedding 与语义相似度&quot;">​</a></h3><p>通用 Embedding 通常把一句话、一段文档、图片或其他对象编码成一个固定长度向量。它常用于：</p><ul><li>语义搜索和 RAG 检索。</li><li>推荐、聚类和去重。</li><li>使用余弦相似度（衡量两个向量方向是否相近的常用方法）比较对象是否相关。</li></ul><p>它与 Token Embedding 的差别在于用途和输出粒度：Token Embedding 是语言模型内部每个 Token 的初始表示；通用 Embedding 往往是为整段内容和相似度任务训练或汇总出的表示。</p><p>“向量相近”表示模型在训练目标下认为内容相似，不自动代表事实相同、立场一致或可以互相替代。</p><h3 id="token、embedding-与-textual-inversion" tabindex="-1">Token、Embedding 与 Textual Inversion <a class="header-anchor" href="#token、embedding-与-textual-inversion" aria-label="Permalink to &quot;Token、Embedding 与 Textual Inversion&quot;">​</a></h3><p>（这个小节提前用到了 AI 绘画章节的“触发词”“文本编码器”概念；还没读到那里时，只需记住：绘画里的 Embedding 与本文讲的文本向量是两回事。）</p><p>在 AI 绘画中，Textual Inversion 会学习一小组向量，并用一个触发词把这些向量送入文本编码器，以表达某个视觉概念。</p><p>它不是：</p><ul><li>新的通用分词算法。</li><li>可直接用于文档语义搜索的通用 Embedding 模型。</li><li>LLM Vocabulary 中天然存在的普通词义。</li></ul><p>因此，本知识库把 <strong>Embedding</strong> 用作通用向量嵌入，把 AI 绘画中的小型提示词嵌入明确称为 <strong>Textual Inversion</strong>。</p><h3 id="中英文-token-数量和成本影响" tabindex="-1">中英文 Token 数量和成本影响 <a class="header-anchor" href="#中英文-token-数量和成本影响" aria-label="Permalink to &quot;中英文 Token 数量和成本影响&quot;">​</a></h3><p>“一个汉字等于一个 Token”或“一个英文单词固定等于 1.3 个 Token”都不是通用规则。</p><p>Token 数量受以下因素共同影响：</p><ul><li>模型的 Tokenizer、Vocabulary 和训练语料。</li><li>文本语言、词频、空格、标点和 Unicode 形式。</li><li>专有名词、代码、数字、罕见字和混合语言。</li><li>聊天模板额外加入的角色标记与特殊 Token。</li></ul><p>常见英文词可能是一个 Token，也可能被拆成多个子词；常见汉字或词组可能独立成 Token，罕见字符也可能退回到多个字节 Token。正确做法是使用目标模型对应的 Tokenizer 实测。</p><p>Token 数量会影响：</p><ul><li>是否超出上下文窗口。</li><li>输入预处理和模型计算量。</li><li>生成延迟与 KV Cache 内存。</li><li>按输入/输出 Token 计费的服务成本。</li></ul><p>本地模型没有 API 账单，但仍会消耗计算时间、显存、内存和电力。</p><h2 id="最小推演-从文本到向量" tabindex="-1">最小推演：从文本到向量 <a class="header-anchor" href="#最小推演-从文本到向量" aria-label="Permalink to &quot;最小推演：从文本到向量&quot;">​</a></h2><p>下面使用一个人为构造的 Vocabulary，不代表任何真实模型：</p><table tabindex="0"><thead><tr><th>Token</th><th style="text-align:right;">ID</th><th>二维 Token Embedding</th></tr></thead><tbody><tr><td><code>[BOS]</code></td><td style="text-align:right;">0</td><td><code>[0.0, 0.0]</code></td></tr><tr><td><code>我</code></td><td style="text-align:right;">1</td><td><code>[0.2, 0.7]</code></td></tr><tr><td><code>喜欢</code></td><td style="text-align:right;">2</td><td><code>[0.6, 0.4]</code></td></tr><tr><td><code>机器</code></td><td style="text-align:right;">3</td><td><code>[0.8, 0.1]</code></td></tr><tr><td><code>学习</code></td><td style="text-align:right;">4</td><td><code>[0.7, 0.2]</code></td></tr><tr><td><code>。</code></td><td style="text-align:right;">5</td><td><code>[0.0, 0.1]</code></td></tr></tbody></table><p>文本：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我喜欢机器学习。</span></span></code></pre></div><p>在这个玩具 Tokenizer 中：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Token:    [BOS]  我  喜欢  机器  学习  。</span></span>
<span class="line"><span>Token ID:    0   1    2     3     4    5</span></span></code></pre></div><p>ID <code>3</code> 会查到向量 <code>[0.8, 0.1]</code>。若这个玩具模型采用“位置向量直接相加”，位置 3 的向量是 <code>[0.0, 0.3]</code>，则送入第一层的表示为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[0.8, 0.1] + [0.0, 0.3] = [0.8, 0.4]</span></span></code></pre></div><p>真实模型的向量通常有数百到数千维，位置机制也未必采用直接相加。这个推演只说明数据流：<strong>字符串 → Token → ID → 初始向量 → 加入位置信息 → 上下文表示</strong>。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>把本页出现的概念放在一起对比：</p><table tabindex="0"><thead><tr><th>概念</th><th>输入</th><th>输出</th><th>主要用途</th><th>语义相似度</th></tr></thead><tbody><tr><td>Tokenizer</td><td>字符串</td><td>Token 或 Token ID 序列</td><td>文本编码与解码</td><td>否</td></tr><tr><td>Token ID</td><td>一个 Token</td><td>整数索引</td><td>查表和序列表示</td><td>否</td></tr><tr><td>Token Embedding</td><td>Token ID</td><td>每个 Token 的初始向量</td><td>语言模型内部计算</td><td>非直接用途</td></tr><tr><td>位置表示</td><td>序列位置</td><td>位置相关信号</td><td>让模型区分顺序</td><td>否</td></tr><tr><td>通用 Embedding</td><td>句子、文档、图片等</td><td>固定长度向量</td><td>搜索、聚类、RAG</td><td>通常用于</td></tr><tr><td>Textual Inversion</td><td>训练图片与触发词</td><td>学到的提示词向量</td><td>触发图像生成概念</td><td>否</td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“Token 就是字或单词”</strong>：Token 由具体 Tokenizer 决定，可能是子词、标点或字节片段。</li><li><strong>“Token ID 大小表示语义强弱”</strong>：ID 只是 Vocabulary 索引。</li><li><strong>“Embedding 就是一种固定算法”</strong>：它是一类向量表示，模型、训练目标和粒度都可能不同。</li><li><strong>“同一个词的向量永远相同”</strong>：初始 Token Embedding 可以相同，但 Transformer 产生的上下文表示会随语境变化。</li><li><strong>“中英文有固定 Token 换算比”</strong>：必须用目标模型的 Tokenizer 对实际文本测量。</li><li><strong>“Textual Inversion 可以直接做 RAG”</strong>：它面向图像生成提示条件，不是通用文档检索模型。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-为什么-token-id-不能直接拿来计算语义距离" tabindex="-1">1. 为什么 Token ID 不能直接拿来计算语义距离？ <a class="header-anchor" href="#_1-为什么-token-id-不能直接拿来计算语义距离" aria-label="Permalink to &quot;1. 为什么 Token ID 不能直接拿来计算语义距离？&quot;">​</a></h3><details><summary>查看答案</summary><p>因为 Token ID 只是 Vocabulary 中的离散索引，编号差值没有语义含义。语义关系需要通过训练得到的向量表示及相应相似度方法衡量。</p></details><h3 id="_2-同一段文本在两个模型里-token-数量不同-是否一定有一个模型分错了" tabindex="-1">2. 同一段文本在两个模型里 Token 数量不同，是否一定有一个模型分错了？ <a class="header-anchor" href="#_2-同一段文本在两个模型里-token-数量不同-是否一定有一个模型分错了" aria-label="Permalink to &quot;2. 同一段文本在两个模型里 Token 数量不同，是否一定有一个模型分错了？&quot;">​</a></h3><details><summary>查看答案</summary><p>不一定。两个模型可能使用不同的规范化规则、子词算法和 Vocabulary，因此可以产生不同但各自有效的切分。</p></details><h3 id="_3-token-embedding-和通用语义-embedding-的主要区别是什么" tabindex="-1">3. Token Embedding 和通用语义 Embedding 的主要区别是什么？ <a class="header-anchor" href="#_3-token-embedding-和通用语义-embedding-的主要区别是什么" aria-label="Permalink to &quot;3. Token Embedding 和通用语义 Embedding 的主要区别是什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>Token Embedding 通常是语言模型内部每个 Token 的初始向量；通用语义 Embedding 通常把整句、文档或其他对象编码为适合相似度比较的固定长度向量。</p></details><h2 id="下一步阅读" tabindex="-1">下一步阅读 <a class="header-anchor" href="#下一步阅读" aria-label="Permalink to &quot;下一步阅读&quot;">​</a></h2><ul><li>上一篇：<a href="/llm/basics">大模型入门</a>：先知道 LLM 在预测什么，再看文本如何被切成 Token。</li><li>下一篇：<a href="/llm/transformer">Transformer 直觉</a>：看 Token 向量进入模型后如何结合上下文形成表示。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://huggingface.co/learn/llm-course/chapter2/4" target="_blank" rel="noreferrer">Hugging Face LLM Course：Tokenizer</a>：官方课程中讲解 Tokenizer 的章节。</li><li><a href="https://huggingface.co/docs/tokenizers/quicktour" target="_blank" rel="noreferrer">Hugging Face Tokenizers：Quicktour</a>：Tokenizers 库的官方快速上手文档。</li><li><a href="https://aclanthology.org/P16-1162/" target="_blank" rel="noreferrer">Sennrich 等：Neural Machine Translation of Rare Words with Subword Units</a>：BPE 子词切分方法的原始论文。</li><li><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">Vaswani 等：Attention Is All You Need</a>：Transformer 架构的原始论文。</li><li><a href="https://arxiv.org/abs/1301.3781" target="_blank" rel="noreferrer">Mikolov 等：Efficient Estimation of Word Representations in Vector Space</a>：word2vec 词向量方法的原始论文。</li><li><a href="https://github.com/openai/tiktoken" target="_blank" rel="noreferrer">OpenAI：tiktoken 开源 Tokenizer</a>：OpenAI 的开源分词器仓库，可实测文本切分。</li></ul>`,68)])])}const g=t(o,[["render",d]]);export{b as __pageData,g as default};
